"""Generate the single downloadable command from maintainable Python source."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
BOOTSTRAP = '''#!/usr/bin/env bash
# Generated by tools/build_node_installer.py. Edit tools/node_installer.py.
set -euo pipefail
for argument in "$@"; do
    if [[ "$argument" == "--help" || "$argument" == "-h" ]]; then
        cat <<'HELP'
Better Pelican Secrets node setup (existing Ubuntu/Debian systemd nodes)
Usage: sudo bash install-node.sh [options]
  --dry-run                 Verify the node and download; change nothing
  --service NAME.service    Existing Wings service (default: wings.service)
  --config /absolute/path   Must match that service's existing --config path
  --tmpfs-size 512M          Capacity for a new tmpfs (default: 256M)
  --panel-ca-file /path      Trusted CA bundle for an existing private Panel CA
  --health-timeout 45        Process health timeout, 5 to 300 seconds

Install and enable the Panel plugin first. Existing node credentials and
server assignments are reused. This restarts Wings, not a host reboot.
HELP
        exit 0
    fi
done
[[ "$EUID" -eq 0 ]] || { echo 'Run this installer using sudo/root.' >&2; exit 1; }
[[ "$(uname -s)" == Linux && "$(uname -m)" == x86_64 ]] || { echo 'Linux amd64 is required.' >&2; exit 1; }
[[ -d /run/systemd/system ]] || { echo 'Run on the node host with systemd, outside Docker.' >&2; exit 1; }
# os-release is the distribution-owned root configuration.
. /etc/os-release
[[ "$ID" == ubuntu || "$ID" == debian ]] || { echo 'Ubuntu/Debian is required.' >&2; exit 1; }
dry_run=false
for argument in "$@"; do [[ "$argument" != --dry-run ]] || dry_run=true; done
if ! /usr/bin/python3 -c 'import sys, yaml; assert sys.version_info >= (3, 10)' >/dev/null 2>&1; then
    if "$dry_run"; then
        echo 'Dry run requires Python 3.10+ and python3-yaml; no packages installed.' >&2
        exit 1
    fi
    export DEBIAN_FRONTEND=noninteractive
    apt-get update
    apt-get install -y --no-install-recommends python3 python3-yaml ca-certificates util-linux
fi
/usr/bin/python3 -c 'import sys, yaml; assert sys.version_info >= (3, 10)' >/dev/null 2>&1 || {
    echo 'Use Ubuntu 22.04+ or Debian 12+ with Python 3.10+.' >&2; exit 1;
}
for program in systemctl systemd-escape findmnt docker; do
    command -v "$program" >/dev/null || { echo "Required command missing: $program" >&2; exit 1; }
done
exec /usr/bin/python3 - "$@" <<'BPS_PYTHON'
'''


def render():
    source = (ROOT / "tools/node_installer.py").read_text(encoding="utf-8").replace("\r\n", "\n")
    return BOOTSTRAP + source.rstrip() + "\nBPS_PYTHON\n"


if __name__ == "__main__":
    (ROOT / "install-node.sh").write_text(render(), encoding="utf-8", newline="\n")
